def _sanitize_and_merge_csv(csv_path: Path, base_csv_text: str, backfill_rows: list[tuple]) -> int:
    csv_path.parent.mkdir(parents=True, exist_ok=True)
    base_df = pd.read_csv(io.StringIO(base_csv_text))
    frames = [base_df]
    if csv_path.exists():
        try:
            existing = pd.read_csv(csv_path)
            if {"Date", "Open", "High", "Low", "Close"}.issubset(existing.columns):
                frames.insert(0, existing[["Date", "Open", "High", "Low", "Close"]])
        except Exception:
            pass
    bf_df = pd.DataFrame(backfill_rows, columns=["Date", "Open", "High", "Low", "Close"])
    frames.append(bf_df)
    merged = pd.concat(frames, ignore_index=True)
    merged["Date"] = pd.to_datetime(merged["Date"].astype(str).str.strip().str[:10], errors="coerce")
    merged = merged.dropna(subset=["Date"]).copy()
    for col in ("Open", "High", "Low", "Close"):
        merged[col] = pd.to_numeric(merged[col], errors="coerce")
    merged = merged.dropna(subset=["Open", "High", "Low", "Close"]).copy()
    merged["High"] = merged[["Open", "High", "Low", "Close"]].max(axis=1)
    merged["Low"] = merged[["Open", "High", "Low", "Close"]].min(axis=1)
    merged["Date"] = merged["Date"].dt.strftime("%Y-%m-%d")
    merged = merged.drop_duplicates(subset=["Date"], keep="last").sort_values("Date").reset_index(drop=True)
    merged.to_csv(csv_path, index=False)
    return len(merged)


def _backfill_research_sqlite(db_path: Path) -> None:
    db_path.parent.mkdir(parents=True, exist_ok=True)
    key_map = {
        "NIFTY": "NSE_INDEX|Nifty 50",
        "BANKNIFTY": "NSE_INDEX|Nifty Bank",
        "INDIA_VIX": "NSE_INDEX|India VIX",
    }
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA journal_mode=WAL;")
        con.execute(
            "CREATE TABLE IF NOT EXISTS candles ("
            "instrument TEXT, interval TEXT, stamp TEXT, "
            "open REAL, high REAL, low REAL, close REAL, volume REAL, oi REAL, "
            "PRIMARY KEY (instrument, interval, stamp))"
        )
        cols = [r[1] for r in con.execute("PRAGMA table_info(candles)").fetchall()]
        for sym, rows in BACKFILL_ROWS.items():
            inst_key = key_map[sym]
            for d_str, o, h, l, c in rows:
                stamp = f"{d_str}T00:00:00+05:30"
                if len(cols) == 9:
                    con.execute(
                        "INSERT OR REPLACE INTO candles VALUES (?,?,?,?,?,?,?,?,?)",
                        (inst_key, "day", stamp, float(o), float(h), float(l), float(c), 0.0, 0.0),
                    )
                elif len(cols) == 8:
                    con.execute(
                        "INSERT OR REPLACE INTO candles VALUES (?,?,?,?,?,?,?,?)",
                        (inst_key, "day", stamp, float(o), float(h), float(l), float(c), 0.0),
                    )


